create or replace function public.admin_add_member(p_email text, p_password text, p_name text, p_role text default 'comercial', p_title text default null) returns uuid language plpgsql security definer set search_path = public, extensions, auth as $$ declare uid uuid := gen_random_uuid(); e text := lower(trim(p_email)); begin if not is_admin() then raise exception 'Somente o administrador pode adicionar membros'; end if; if position('@' in e) < 2 or position('.' in split_part(e, '@', 2)) < 2 then raise exception 'E-mail inválido'; end if; if length(coalesce(p_password, '')) < 6 then raise exception 'A senha precisa ter pelo menos 6 caracteres'; end if; if p_role not in ('admin', 'comercial') then raise exception 'Acesso inválido'; end if; if exists (select 1 from auth.users where lower(email) = e) then raise exception 'Já existe um usuário com este e-mail'; end if; insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at, confirmation_token, email_change, email_change_token_new, recovery_token) values ('00000000-0000-0000-0000-000000000000', uid, 'authenticated', 'authenticated', e, extensions.crypt(p_password, extensions.gen_salt('bf')), now(), jsonb_build_object('provider', 'email', 'providers', jsonb_build_array('email')), jsonb_build_object('name', p_name), now(), now(), '', '', '', ''); insert into auth.identities (id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at) values (gen_random_uuid(), uid, uid::text, jsonb_build_object('sub', uid::text, 'email', e, 'email_verified', true), 'email', now(), now(), now()); insert into public.profiles (id, email, name) values (uid, e, p_name) on conflict (id) do nothing; update public.profiles set agency_id = my_agency(), role = p_role, name = coalesce(nullif(trim(p_name), ''), split_part(e, '@', 1)), title = p_title where id = uid; return uid; end $$; create or replace function public.admin_remove_member(target uuid) returns void language plpgsql security definer set search_path = public, auth as $$ begin if not is_admin() then raise exception 'Somente o administrador pode remover membros'; end if; if target = auth.uid() then raise exception 'Você não pode remover a si mesmo'; end if; if not exists (select 1 from public.profiles where id = target and agency_id = my_agency()) then raise exception 'Membro não encontrado'; end if; update public.clients set owner = auth.uid() where owner = target; update public.content set assignee = auth.uid() where assignee = target; delete from public.tasks where assignee = target; delete from public.messages where user_id = target; delete from public.activity where user_id = target; delete from auth.users where id = target; end $$; revoke all on function public.admin_add_member(text, text, text, text, text) from public, anon; grant execute on function public.admin_add_member(text, text, text, text, text) to authenticated; revoke all on function public.admin_remove_member(uuid) from public, anon; grant execute on function public.admin_remove_member(uuid) to authenticated;
